import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;

@RestController
@RequestMapping("/api/account")
public class WithdrawController {

    @Autowired
    private AccountRepository accountRepo;

    @PostMapping("/withdraw")
    public Result withdraw(@RequestBody WithdrawRequest req) {
        Account account = accountRepo.findById(req.getAccountId()).orElseThrow();
        if (account.getBalance() >= req.getAmount()) {
            account.setBalance(account.getBalance() - req.getAmount());
            accountRepo.save(account);
        }
        return Result.ok(account.getBalance());
    }
}
